import itertools
def f(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=max(cnt,key=lambda x:cnt[x])
    o=[r[:] for r in g]
    for c in cnt:
        if c==bg: continue
        pts=[(r,cc) for r in range(h) for cc in range(w) if g[r][cc]==c]
        for a,b in itertools.combinations(pts,2):
            if a[0]==b[0]:
                lo,hi=sorted((a[1],b[1]))
                ok=all(g[a[0]][k]==bg for k in range(lo+1,hi))
                if ok:
                    for k in range(lo+1,hi): o[a[0]][k]=c
            elif a[1]==b[1]:
                lo,hi=sorted((a[0],b[0]))
                ok=all(g[k][a[1]]==bg for k in range(lo+1,hi))
                if ok:
                    for k in range(lo+1,hi): o[k][a[1]]=c
    return o
