            lo,hi=cols[0],cols[-1]
            if all(g[r][c]==0 for c in range(lo+1,hi)):
                for c in range(lo+1,hi): o[r][c]=k
        # vertical: only in rows with no nonzero cells
        blank={r for r in range(h) if all(v==0 for v in g[r])}
        for c in {y for x,y in pts}:
            rows=sorted(r for rr,cc in pts if cc==c)
            lo,hi=rows[0],rows[-1]
            for r in range(lo+1,hi):
                if r in blank:
                    o[r][c]=k
    return o
